begin;
do $$ declare uid uuid:=gen_random_uuid();failed boolean;begin
 insert into auth.users(id,email,email_confirmed_at) values(uid,'bootstrap-fixture@example.invalid',null);
 failed:=false;begin perform public.memocious_operator_bootstrap(uid,encode(sha256(convert_to('bootstrap-fixture@example.invalid','UTF8')),'hex'));exception when insufficient_privilege then failed:=true;end;
 if not failed then raise exception 'Unverified bootstrap accepted';end if;
 update auth.users set email_confirmed_at=now() where id=uid;
 execute 'set local role authenticated';
 failed:=false;begin perform public.memocious_operator_bootstrap(uid,encode(sha256(convert_to('bootstrap-fixture@example.invalid','UTF8')),'hex'));exception when insufficient_privilege then failed:=true;end;
 if not failed then raise exception 'Browser bootstrap accepted';end if;execute 'reset role';
 execute 'set local role service_role';perform public.memocious_operator_bootstrap(uid,encode(sha256(convert_to('bootstrap-fixture@example.invalid','UTF8')),'hex'));execute 'reset role';
 if not exists(select 1 from memocious_private.admin_users where user_id=uid and role='owner') then raise exception 'Operator bootstrap failed';end if;
 delete from memocious_private.admin_users where user_id=uid;
end $$;
do $$
declare uid uuid:=gen_random_uuid();sid uuid;pid uuid;cid uuid;oid uuid;v int;res jsonb;plan jsonb;failed boolean;media uuid;iid uuid;gsid uuid;order_result jsonb;chosen uuid;other_choice uuid;n int;
begin
 insert into auth.users(id,email_confirmed_at) values(uid,now());
 if not exists(select 1 from memocious.profiles where user_id=uid and full_name='') then raise exception 'Signup profile missing';end if;
 insert into memocious_private.admin_users(user_id,role) values(uid,'owner');
 sid:=public.memocious_session_open(repeat('c',64),repeat('d',64),uid,'admin','encrypted-test-tokens','1');
 failed:=false;begin perform public.memocious_admin_workspace(sid);exception when insufficient_privilege then failed:=true;end;
 if not failed then raise exception 'aal1 admin read succeeded';end if;
 failed:=false;begin perform public.memocious_admin_product(sid,null,1,'create','{"name":"Attack","slug":"attack"}');exception when insufficient_privilege then failed:=true;end;
 if not failed then raise exception 'aal1 write succeeded';end if;
 perform public.memocious_session_mfa(sid,repeat('e',64),repeat('f',64),'encrypted-test-tokens-aal2');
 execute 'set local role service_role';
 select id into cid from memocious.categories where slug='gift-hampers';
 res:=public.memocious_admin_product(sid,null,1,'create',jsonb_build_object('name','Owner product','slug','owner-product','pricePaise',10000,'maxPricePaise',20000,'moq',5,'categories',jsonb_build_array(cid),'messageLimit',12,'options','[{"kind":"addon","label":"Wrapping","required":true,"maxCount":1,"values":[{"label":"Rose","deltaPaise":200},{"label":"Gold","deltaPaise":300}]}]'::jsonb));
 pid:=(res->>'id')::uuid;v:=(res->>'version')::int;
 if not exists(select 1 from memocious.products where id=pid and not active and moq=5 and price_paise=10000) then raise exception 'Private create failed';end if;
 failed:=false;begin perform public.memocious_admin_product(sid,pid,v,'show','{}');exception when invalid_parameter_value then failed:=true;end;
 if not failed then raise exception 'Publish without sanitized media accepted';end if;
 media:=public.memocious_media_begin(sid,pid,1024,'Test photograph');
 if public.memocious_media_claim(sid,media)->>'bytes'<>'1024' then raise exception 'Reservation failed';end if;
 failed:=false;begin perform public.memocious_media_claim(sid,media);exception when insufficient_privilege then failed:=true;end;
 if not failed then raise exception 'Upload ticket reused';end if;
 iid:=public.memocious_media_ready(sid,media,100,100,500,repeat('a',64));
 if public.memocious_media_public(iid) is not null then raise exception 'Private media exposed';end if;
 select version into v from memocious.products where id=pid;
 perform public.memocious_media_update(sid,iid,v,'publish','Published test photograph',0);
 select version into v from memocious.products where id=pid;
 res:=public.memocious_admin_product(sid,pid,v,'show','{}');v:=(res->>'version')::int;
 if public.memocious_product('owner-product') is null or public.memocious_media_public(iid) is null then raise exception 'Publication failed';end if;
 update memocious.site_settings set value='"447700900123"'::jsonb where key='whatsapp_number';update memocious.site_settings set value='true'::jsonb where key='policies_approved';
 gsid:=public.memocious_session_open(repeat('1',64),repeat('2',64),null,'guest',null,'1');
 select v.id into chosen from memocious.option_values v join memocious.product_options o on o.id=v.option_id where o.product_id=pid order by v.sort_order limit 1;
 select v.id into other_choice from memocious.option_values v join memocious.product_options o on o.id=v.option_id where o.product_id=pid and v.id<>chosen limit 1;
 failed:=false;begin perform public.memocious_enquiry(gsid,gen_random_uuid(),pid,5,array[chosen,other_choice],'',null,'','');exception when invalid_parameter_value then failed:=true;end;
 if not failed then raise exception 'Multiple selections over maxCount accepted';end if;
 failed:=false;begin perform public.memocious_enquiry(gsid,gen_random_uuid(),pid,4,array[chosen],'',null,'','');exception when invalid_parameter_value then failed:=true;end;
 if not failed then raise exception 'Quantity below MOQ accepted';end if;
 failed:=false;begin perform public.memocious_enquiry(gsid,gen_random_uuid(),pid,5,array[chosen],repeat('a',13),null,'','');exception when invalid_parameter_value then failed:=true;end;
 if not failed then raise exception 'Product message limit bypassed';end if;
 order_result:=public.memocious_enquiry(gsid,gen_random_uuid(),pid,5,array[chosen],'A safe note',null,'','');
 for n in 1..9 loop perform public.memocious_media_begin(sid,pid,100,'Quota fixture');end loop;
 failed:=false;begin perform public.memocious_media_begin(sid,pid,100,'Over quota');exception when sqlstate '54000' then failed:=true;end;
 if not failed then raise exception 'Upload quota bypassed';end if;
 plan:=public.memocious_admin_delete(sid,array[pid],'soft');
 res:=public.memocious_admin_product(sid,pid,v,'edit','{"description":"Changed after confirmation"}');v:=(res->>'version')::int;
 failed:=false;begin perform public.memocious_admin_delete(sid,array[pid],'soft',plan->>'digest','DELETE 1');exception when serialization_failure then failed:=true;end;
 if not failed then raise exception 'Stale bulk confirmation accepted';end if;
 plan:=public.memocious_admin_delete(sid,array[pid],'soft');
 perform public.memocious_admin_delete(sid,array[pid],'soft',plan->>'digest','DELETE 1');
 if public.memocious_media_public(iid) is not null or public.memocious_product('owner-product') is not null then raise exception 'Deleted publication exposed';end if;
 plan:=public.memocious_admin_delete(sid,null,'permanent');perform public.memocious_admin_delete(sid,null,'permanent',plan->>'digest','DELETE '||(plan->>'count'));
 if exists(select 1 from memocious.products where id=pid) then raise exception 'Purge failed';end if;
 if not exists(select 1 from memocious.order_items i join memocious.orders o on o.id=i.order_id where o.code=order_result->>'code' and i.product_id is null and i.product_name='Owner product' and i.quantity=5) then raise exception 'Bulk deletion lost history';end if;
 for n in 1..6 loop res:=public.memocious_rate_limit('auth',repeat('9',64),repeat('8',64));if (res->>'allowed')::boolean is distinct from (n<=5) then raise exception 'Distributed auth quota failed';end if;end loop;
 -- Cycle edits are serialized by the same catalogue lock and rejected by the trigger.
 select id into cid from memocious.categories where slug='gift-hampers';select id into oid from memocious.categories where slug='festive-hampers';
 failed:=false;begin perform public.memocious_admin_taxonomy(sid,'category',cid,1,jsonb_build_object('label','Hamper','slug','gift-hampers','parentId',oid,'sortOrder',0,'active',true));exception when raise_exception then if sqlerrm<>'Taxonomy cycle rejected' then raise;end if;failed:=true;end;
 if not failed then raise exception 'Taxonomy cycle accepted';end if;
 perform public.memocious_admin_settings(sid,'{"brand":"Studio test","tagline":"Test","contactEmail":"","whatsappNumber":null,"requireLogin":true}');
 execute 'set local role anon';
 if public.memocious_catalogue('{}')->'products'<>'[]'::jsonb or public.memocious_taxonomy()->'categories'<>'[]'::jsonb then raise exception 'Raw provider gate bypass';end if;
 execute 'reset role';
 update memocious_private.app_sessions set mfa_verified_at=now()-interval '6 minutes' where id=sid;
 failed:=false;begin perform public.memocious_admin_delete(sid,null,'soft');exception when insufficient_privilege then failed:=true;end;
 if not failed then raise exception 'Stale MFA deletion accepted';end if;
 update memocious_private.admin_users set active=false where user_id=uid;
 failed:=false;begin perform public.memocious_admin_workspace(sid);exception when insufficient_privilege then failed:=true;end;
 if not failed then raise exception 'Revoked owner accepted';end if;
end $$;
rollback;
